def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    threshold = 3000

    count = (1 if v1 > threshold else 0) + (1 if v2 > threshold else 0)

    return {
        "value": count,
        "trace": {
            "v1": v1,
            "v2": v2,
            "threshold": threshold,
            "count": count,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "years"
            }
        }
    }
